def load_pacific_plate_from_file(plates_filepath):
    """
    Load the Pacific plate polygon directly from the plates GeoJSON file.
    """
    with open(plates_filepath, 'r') as f:
        geojson_data = json.load(f)

    for feature in geojson_data.get('features', []):
        props = feature.get('properties', {})
        if props.get('PlateName') == 'PA' or props.get('Name') == 'PA':
            geom = shape(feature['geometry'])
            if geom.is_valid:
                return geom
            else:
                return geom.buffer(0)  # Fix invalid geometry

    return None

